using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;

namespace AdaptiveCards
{
    /// <summary>
    /// A converter that handles fallback scenarios for AdaptiveCards elements.
    /// </summary>
    public class AdaptiveFallbackConverter : JsonConverter<AdaptiveFallbackElement>, ILogWarnings
    {
        /// <summary>
        /// A list of warnings generated by this converter.
        /// </summary>
        public List<AdaptiveWarning> Warnings { get; set; } = new List<AdaptiveWarning>();

        /// <summary>
        /// The <see cref="ParseContext"/> for element tracking.
        /// </summary>
        public ParseContext ParseContext { get; set; } = new ParseContext();

        /// <summary>
        /// Initializes a new instance for serialization.
        /// </summary>
        public AdaptiveFallbackConverter() { }

        /// <summary>
        /// Initializes a new instance for deserialization with shared state.
        /// </summary>
        public AdaptiveFallbackConverter(List<AdaptiveWarning> warnings, ParseContext parseContext)
        {
            Warnings = warnings ?? new List<AdaptiveWarning>();
            ParseContext = parseContext ?? new ParseContext();
        }

        /// <summary>
        /// State tracking to determine whether we're currently processing a fallback request.
        /// </summary>
        /// <remarks>
        /// Marked <c>[ThreadStatic]</c> to avoid race conditions when multiple threads parse
        /// cards concurrently. Each thread has its own copy of this flag so that one thread's
        /// fallback state cannot corrupt another thread's ID collision detection.
        /// </remarks>
        [System.ThreadStatic]
        private static bool _isInFallback;

        /// <inheritdoc cref="_isInFallback"/>
        public static bool IsInFallback
        {
            get => _isInFallback;
            set => _isInFallback = value;
        }

        /// <inheritdoc />
        public override AdaptiveFallbackElement Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            if (reader.TokenType == JsonTokenType.String)
            {
                string stringValue = reader.GetString();
                if (stringValue == "drop")
                {
                    return new AdaptiveFallbackElement(AdaptiveFallbackElement.AdaptiveFallbackType.Drop);
                }
                throw new AdaptiveSerializationException("The only valid string value for the fallback property is 'drop'.");
            }

            if (reader.TokenType == JsonTokenType.StartObject)
            {
                var node = JsonNode.Parse(ref reader);
                var jObject = node.AsObject();

                var typeName = AdaptiveTypedElementConverter.GetElementTypeName(typeof(AdaptiveTypedElement), jObject);
                Type type;
                if (!AdaptiveTypedElementConverter.TypedElementTypes.Value.TryGetValue(typeName, out type))
                {
                    type = typeof(AdaptiveUnknownElement);
                }

                IsInFallback = true;
                string objectId = jObject["id"]?.GetValue<string>();
                AdaptiveInternalID internalID = AdaptiveInternalID.Next();

                ParseContext.PushElement(objectId, internalID);
                var result = (AdaptiveTypedElement)node.Deserialize(type, options);
                ParseContext.PopElement();
                IsInFallback = false;

                return new AdaptiveFallbackElement(AdaptiveFallbackElement.AdaptiveFallbackType.Content)
                {
                    Content = result
                };
            }

            throw new AdaptiveSerializationException("Invalid value for fallback");
        }

        /// <inheritdoc />
        public override void Write(Utf8JsonWriter writer, AdaptiveFallbackElement value, JsonSerializerOptions options)
        {
            if (value != null)
            {
                if (value.Type != AdaptiveFallbackElement.AdaptiveFallbackType.None)
                {
                    if (value.Type == AdaptiveFallbackElement.AdaptiveFallbackType.Drop)
                    {
                        writer.WriteStringValue(AdaptiveFallbackElement.drop);
                    }
                    else
                    {
                        JsonSerializer.Serialize(writer, value.Content, value.Content.GetType(), options);
                    }
                }
            }
        }

    }
}
